<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};

final class EmergencyProcedureService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly ?WorkflowLanguageService $languages=null) {}
    public function workspace(array $input): array {
        $this->fields($input,['site_id']);$site=$this->access->requireSite($input['site_id']??null);$params=['company'=>$this->company(),'site'=>$site['site_id']];
        $procedures=$this->db->fetchAll('SELECT * FROM emergency_procedures WHERE company_id=:company AND site_id=:site ORDER BY revision DESC LIMIT 50',$params);foreach($procedures as&$p){$p['steps']=json_decode($p['steps_json'],true,512,JSON_THROW_ON_ERROR);unset($p['steps_json']);if($this->languages!==null){$t=$this->languages->read(['entity_kind'=>'EMERGENCY_PROCEDURE','entity_id'=>$p['procedure_id']]);$p=array_merge($p,$t['content'],['display_language'=>$t['display_language'],'translation_fallback'=>$t['fallback']]);}}unset($p);
        $exercises=$this->db->fetchAll('SELECT * FROM emergency_exercises WHERE company_id=:company AND site_id=:site ORDER BY exercise_id DESC LIMIT 100',$params);foreach($exercises as&$e){$e['roll_call']=$this->db->fetchAll('SELECT * FROM emergency_roll_calls WHERE company_id=:company AND exercise_id=:id ORDER BY participant_id',['company'=>$this->company(),'id'=>$e['exercise_id']]);$e['completed_steps']=$this->db->fetchAll('SELECT * FROM emergency_step_records WHERE company_id=:company AND exercise_id=:id ORDER BY step_number',['company'=>$this->company(),'id'=>$e['exercise_id']]);$pinned=$this->row('emergency_procedures','procedure_id',$e['procedure_id']);$pinned['steps']=json_decode($pinned['steps_json'],true,512,JSON_THROW_ON_ERROR);unset($pinned['steps_json']);if($this->languages!==null){$t=$this->languages->read(['entity_kind'=>'EMERGENCY_PROCEDURE','entity_id'=>$pinned['procedure_id']]);$pinned=array_merge($pinned,$t['content'],['display_language'=>$t['display_language'],'translation_fallback'=>$t['fallback']]);}$e['procedure']=$pinned;$e['unaccounted_count']=count(array_filter($e['roll_call'],static fn($r)=>$r['state']!=='SAFE'));}unset($e);
        return ['site_id'=>$site['site_id'],'procedures'=>$procedures,'exercises'=>$exercises,'note'=>'Recorded procedures, roll calls and drills do not dispatch emergency services. Use site radio/phone arrangements. Roll calls include only the participants explicitly entered for this event.'];
    }
    public function publish(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['site_id','expected_revision','title','steps','emergency_contacts','assembly_point']);$site=$this->access->requireSite($input['site_id']??null);$old=$this->db->fetch('SELECT revision FROM emergency_procedures WHERE company_id=:company AND site_id=:site ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$site['site_id']]);$revision=(int)($old['revision']??0);if($this->number($input['expected_revision']??null,0)!==$revision)throw HttpException::conflict('Procedure changed. Refresh first.');$steps=$input['steps']??null;if(!is_array($steps)||!array_is_list($steps)||count($steps)<1||count($steps)>30)throw HttpException::unprocessable('Enter 1–30 response steps.');$steps=array_map(fn($s)=>$this->text($s,1000),$steps);
        $this->db->execute('INSERT INTO emergency_procedures(company_id,site_id,revision,title,steps_json,emergency_contacts,assembly_point,published_by_user_id,published_at) VALUES(:company,:site,:revision,:title,:steps,:contacts,:assembly,:actor,:now)',['company'=>$this->company(),'site'=>$site['site_id'],'revision'=>$revision+1,'title'=>$this->text($input['title']??null,150),'steps'=>json_encode($steps,JSON_THROW_ON_ERROR),'contacts'=>$this->text($input['emergency_contacts']??null,4000),'assembly'=>$this->text($input['assembly_point']??null,500),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('emergency_procedure');
    });}
    public function start(array $input): array {return $this->atomic(function()use($input){
        $this->fields($input,['procedure_id','exercise_type','title','participants']);$p=$this->row('emergency_procedures','procedure_id',$input['procedure_id']??null);$this->access->requireSite($p['site_id']);$latest=$this->db->fetch('SELECT procedure_id FROM emergency_procedures WHERE company_id=:company AND site_id=:site ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$p['site_id']]);if((string)$latest['procedure_id']!==(string)$p['procedure_id'])throw HttpException::conflict('Start using the current procedure.');
        $type=$input['exercise_type']??null;if(!in_array($type,['DRILL','EMERGENCY'],true))throw HttpException::unprocessable('Choose DRILL or EMERGENCY explicitly.');$participants=$input['participants']??null;if(!is_array($participants)||!array_is_list($participants)||count($participants)<1||count($participants)>300)throw HttpException::unprocessable('Enter 1–300 participant names or identifying labels.');$names=array_map(fn($n)=>$this->text($n,150),$participants);if(count(array_unique($names))!==count($names))throw HttpException::unprocessable('Use unique participant labels, including an identifier for duplicate names.');
        $this->db->execute('INSERT INTO emergency_exercises(company_id,site_id,procedure_id,exercise_type,title,started_by_user_id,started_at) VALUES(:company,:site,:procedure,:type,:title,:actor,:now)',['company'=>$this->company(),'site'=>$p['site_id'],'procedure'=>$p['procedure_id'],'type'=>$type,'title'=>$this->text($input['title']??null,150),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$result=$this->created('emergency_exercise');foreach($names as$name)$this->db->execute('INSERT INTO emergency_roll_calls(company_id,exercise_id,participant_name) VALUES(:company,:exercise,:name)',['company'=>$this->company(),'exercise'=>$result['id'],'name'=>$name]);return $result;
    });}
    private function active(string $id): array {$e=$this->row('emergency_exercises','exercise_id',$id);$this->access->requireSite($e['site_id']);if($e['state']!=='ACTIVE')throw HttpException::conflict('This event has ended.');return $e;}
    public function rollCall(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['expected_revision','state','notes']);$r=$this->row('emergency_roll_calls','participant_id',$id);$this->active((string)$r['exercise_id']);if($this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Participant status changed.');$state=$input['state']??null;if(!in_array($state,['UNKNOWN','SAFE','ASSISTANCE','MISSING'],true))throw HttpException::unprocessable('Choose a supported roll-call status.');
        $this->db->execute('UPDATE emergency_roll_calls SET state=:state,revision=revision+1,notes=:notes,checked_by_user_id=:actor,checked_at=:now WHERE company_id=:company AND participant_id=:id',['state'=>$state,'notes'=>$this->text($input['notes']??null,1000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->db->execute('UPDATE emergency_exercises SET revision=revision+1 WHERE company_id=:company AND exercise_id=:id',['company'=>$this->company(),'id'=>$r['exercise_id']]);$this->audit->record('emergency_roll_call','status_recorded',$id,[],[],['state'=>$state]);return ['state'=>$state];
    });}
    public function completeStep(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['step_number','notes']);$e=$this->active($id);$p=$this->row('emergency_procedures','procedure_id',$e['procedure_id']);$steps=json_decode($p['steps_json'],true,512,JSON_THROW_ON_ERROR);$step=$this->number($input['step_number']??null,1,count($steps));if($this->db->fetch('SELECT step_record_id FROM emergency_step_records WHERE company_id=:company AND exercise_id=:id AND step_number=:step',['company'=>$this->company(),'id'=>$id,'step'=>$step]))throw HttpException::conflict('Step already recorded.');
        $this->db->execute('INSERT INTO emergency_step_records(company_id,exercise_id,step_number,notes,completed_by_user_id,completed_at) VALUES(:company,:exercise,:step,:notes,:actor,:now)',['company'=>$this->company(),'exercise'=>$id,'step'=>$step,'notes'=>$this->text($input['notes']??null,1000),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$this->db->execute('UPDATE emergency_exercises SET revision=revision+1 WHERE company_id=:company AND exercise_id=:id',['company'=>$this->company(),'id'=>$id]);$this->audit->record('emergency_exercise','step_recorded',$id,[],[],['step'=>$step]);return ['recorded'=>true];
    });}
    public function finish(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['expected_revision','debrief']);$e=$this->active($id);if($this->number($input['expected_revision']??null)!==(int)$e['revision'])throw HttpException::conflict('Event changed. Refresh the roll call first.');$p=$this->row('emergency_procedures','procedure_id',$e['procedure_id']);$steps=count(json_decode($p['steps_json'],true,512,JSON_THROW_ON_ERROR));$done=(int)$this->db->fetch('SELECT COUNT(*) AS n FROM emergency_step_records WHERE company_id=:company AND exercise_id=:id',['company'=>$this->company(),'id'=>$id])['n'];$unaccounted=(int)$this->db->fetch("SELECT COUNT(*) AS n FROM emergency_roll_calls WHERE company_id=:company AND exercise_id=:id AND state<>'SAFE'",['company'=>$this->company(),'id'=>$id])['n'];
        $state=$done===$steps&&$unaccounted===0?'CLOSED':'CLOSED_WITH_FINDINGS';if($e['exercise_type']==='EMERGENCY'&&$state!=='CLOSED')throw HttpException::conflict('An emergency cannot be marked closed until every step is recorded and all listed participants are safe.');
        $this->db->execute('UPDATE emergency_exercises SET state=:state,revision=revision+1,closed_by_user_id=:actor,closed_at=:now,debrief=:debrief WHERE company_id=:company AND exercise_id=:id',['state'=>$state,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'debrief'=>$this->text($input['debrief']??null,6000),'company'=>$this->company(),'id'=>$id]);$this->audit->record('emergency_exercise','ended',$id,[],[],['state'=>$state,'unaccounted'=>$unaccounted]);return ['state'=>$state,'unaccounted_count'=>$unaccounted];
    });}
}
